test('F5-H 28 fresh057 installed056 upgrade replay and old checksums are preserved',function():void{$db=isolatedDomainDb();$root=dirname(__DIR__);$dir=$root.'/storage/h-prefix-'.bin2hex(random_bytes(5));mkdir($dir,0700);foreach(glob($root.'/migrations/*.php') as $file){if(basename($file)<'057'){copy($file,$dir.'/'.basename($file));}}same(56,count((new Migrator($db,$dir))->migrate()));$old=$db->execute('SELECT * FROM schema_migrations ORDER BY version')->fetchAll();$m=new Migrator($db,$root.'/migrations');same(['057_support_ticket_split.php'],$m->migrate());same([],$m->migrate());$m->assertReady();same($old,$db->execute("SELECT * FROM schema_migrations WHERE version<'057' ORDER BY version")->fetchAll());$db=isolatedDomainDb();$m=new Migrator($db,$root.'/migrations');same(57,count($m->migrate()));same([],$m->migrate());$m->assertReady();});
